DO $review$
DECLARE v jsonb; s public.est_source_review%rowtype; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; qid uuid; p jsonb; pid uuid;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "clean:HOA 114", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "1376f4fc-4bb5-53df-9ca9-14323cbd6537", "stem": "What is the sum of the solutions of x²−5x+2=9x?", "choices": [{"key": "A", "text": "−5/2"}, {"key": "B", "text": "5/2"}, {"key": "C", "text": "14"}, {"key": "D", "text": "−14"}], "type": "mcq", "correct": "C", "explanation": "Move all terms to one side: x²−14x+2=0. The sum of roots is −b/a=14.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Original PDF visually checked; isolated complete question and independently verified the solution.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 71, "extra_sources": [], "parts": [{"label": "Q4", "question_id": "220d9415-6429-5213-9f81-a7e27fa71003", "stem": "The cumulative frequency graph records masses for 40 students. What is the approximate median mass?", "choices": [{"key": "A", "text": "15 g"}, {"key": "B", "text": "22 g"}, {"key": "C", "text": "20 g"}, {"key": "D", "text": "11 g"}], "type": "mcq", "correct": "B", "explanation": "Half of 40 is 20. Read across from cumulative frequency 20 to the curve and then down to the mass axis. The mass is approximately 22 g.", "topic": "Statistics, Probability & Data Analysis", "note": "Rephrased the broken 50% sentence as the median; retained the original graph.", "assets": {"figure": "data:image/jpeg;base64,"}}]}, {"id": "clean:HOA 115", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "c35384b2-804e-53b0-ae27-2bd69ee4598c", "stem": "Which set is the complete solution of |x−3|>3?", "choices": [{"key": "A", "text": "x<0 or x>6"}, {"key": "B", "text": "x>0"}, {"key": "C", "text": "x>−1"}, {"key": "D", "text": "x>2"}], "type": "mcq", "correct": "A", "explanation": "An absolute value exceeds 3 when x−3>3 or x−3<−3. These give x>6 or x<0. The endpoints are excluded.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Original choice A was corrupted and no visible option gave the complete solution. Replaced A with the mathematically verified union; documented source correction.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 72, "extra_sources": [], "parts": [{"label": "Q6", "question_id": "b9411700-e741-522a-9f4d-ff86bdb4ed2a", "stem": "The distance between (2,11) and (4,y) is 2√17. Which listed value could y have?", "choices": [{"key": "A", "text": "1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "4"}, {"key": "D", "text": "3"}], "type": "mcq", "correct": "D", "explanation": "Squaring the distance equation gives 4+(y−11)²=68. Thus y−11=±8 and y=3 or 19. Only 3 is listed; the wording asks which value could occur.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Split from the original shared crop; original PDF visually checked and solution independently verified."}, {"label": "Q7", "question_id": "7a00e223-1162-5c4e-b946-24de0ae173da", "stem": "How many ordered-pair solutions does the system y=−x+8 and x+y=7 have?", "choices": [], "type": "grid_in", "correct": "0", "explanation": "The first equation is x+y=8. It cannot hold simultaneously with x+y=7, so there are zero solutions.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Used numeric response for the count because fractional distractors are unclear."}, {"label": "Q8", "question_id": "22a3c187-8b7d-5107-ac9d-442d7bb0d621", "stem": "Let f(x)=2√(x+3). What is f(13)+2?", "choices": [{"key": "A", "text": "2"}, {"key": "B", "text": "8"}, {"key": "C", "text": "10"}, {"key": "D", "text": "12"}], "type": "mcq", "correct": "C", "explanation": "f(13)=2√16=8. Adding 2 gives 10.", "topic": "Functions, Transformations & Graphs", "note": "Split from the original shared crop; original PDF visually checked and solution independently verified."}, {"label": "Q9", "question_id": "be75574a-9839-51d0-a678-79bb7808a5ea", "stem": "What is the real solution of −x²+14x−49=0?", "choices": [], "type": "grid_in", "correct": "7", "explanation": "The equation is −(x−7)²=0, hence x=7. Substitution gives −49+98−49=0.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Removed the original invalid y=7 distractor by using numeric response."}, {"label": "Q10", "question_id": "e1a6ad5f-2229-55cc-9a53-fdd60b87ea34", "stem": "What is the least integer x satisfying 2(3x−5)≥4x+12?", "choices": [{"key": "A", "text": "11"}, {"key": "B", "text": "1/2"}, {"key": "C", "text": "11/2"}, {"key": "D", "text": "10"}], "type": "mcq", "correct": "A", "explanation": "Expand and collect terms: 6x−10≥4x+12, so 2x≥22 and x≥11. Equality is allowed, making 11 the least integer.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Split from the original shared crop; original PDF visually checked and solution independently verified."}]}, {"id": "clean:HOA 116", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "32dab31e-cd82-5355-bec6-95c6cbb8abf2", "stem": "For a fixed positive real x, the real number a satisfies 3x≥a. What is the greatest possible value of a/11?", "choices": [{"key": "A", "text": "11/x"}, {"key": "B", "text": "1/11"}, {"key": "C", "text": "3x/11"}, {"key": "D", "text": "3x/13"}], "type": "mcq", "correct": "C", "explanation": "Divide a≤3x by the positive number 11 to get a/11≤3x/11. Equality is attained when a=3x.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Recovered choice D from the next crop. Specified positive x to keep all original expressions defined.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 73, "extra_sources": []}, {"id": "clean:HOA 117", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "6421b7b8-925d-50fe-87eb-cd960b240d27", "stem": "For y≥−1/3, let x=√(3y+1). What is 2x²+3?", "choices": [{"key": "A", "text": "6y+2"}, {"key": "B", "text": "6y+5"}, {"key": "C", "text": "6y+3"}, {"key": "D", "text": "1+y"}], "type": "mcq", "correct": "B", "explanation": "Squaring gives x²=3y+1. Then 2x²+3=2(3y+1)+3=6y+5.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Original PDF visually checked; isolated complete question and independently verified the solution.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 73, "extra_sources": []}, {"id": "clean:HOA 118", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "b74966d4-817a-547e-9a4a-963ba4bea58f", "stem": "What is the product of the roots of 2x²+7x+3=0?", "choices": [{"key": "A", "text": "−7/2"}, {"key": "B", "text": "−1.5"}, {"key": "C", "text": "1"}, {"key": "D", "text": "1.5"}], "type": "mcq", "correct": "D", "explanation": "The factorization is (2x+1)(x+3)=0. The roots −1/2 and −3 have product 3/2=1.5. Equivalently, the product is c/a=3/2.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Original PDF visually checked; isolated complete question and independently verified the solution.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 73, "extra_sources": []}, {"id": "clean:HOA 119", "old_status": "ocr_screened_not_verified", "status": "needs_source_reconstruction", "note": "Enlarged the original formula, but its numerator and denominator exponents and requested power of m remain ambiguous at the source resolution. The surviving choices 7,−3,3,1/3 do not resolve the transcription. A sharper original is needed; no answer inferred.", "correct": null}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action=coalesce(v->>'audit_action','source_review_20260928') AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF v->>'status'='ready' AND qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260928','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES(coalesce(v->>'audit_action','source_review_20260928'),'source_review',s.id,
    jsonb_build_object('before_source',to_jsonb(s),'before_question',to_jsonb(q),'before_key',to_jsonb(k),'decision',v-'assets'-'before'));
  IF v->>'status'='ready' THEN
   IF v->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') c WHERE c->>'key'=v->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid key %',s.id; END IF;
   IF v->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(v->'correct')='array' THEN v->'correct'->0 ELSE v->'correct' END,v->'correct') THEN RAISE EXCEPTION 'Grader rejects %',s.id; END IF;
   a=(coalesce(q.assets,'{}'::jsonb)-'release_hold_reason')||coalesce(v->'assets','{}'::jsonb)||jsonb_build_object(
    'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check',
    'verification_note',v->>'note','source_review_id',s.id,'verification_source',s.source_document||' page '||s.source_page);
   IF q.id IS NULL THEN
    a=a||jsonb_build_object('source','reviewed-bank-20260928','source_code',s.source_code,'source_document',s.source_document,'source_page',s.source_page);
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(qid,s.track_id,v->>'topic','medium',v->>'type',v->>'stem',v->'choices',a);
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'correct',v->>'explanation');
   ELSE
    UPDATE public.questions SET topic=v->>'topic',type=v->>'type',stem=v->>'stem',choices=v->'choices',assets=a WHERE id=qid;
    UPDATE public.question_keys SET correct=v->'correct',explanation=v->>'explanation' WHERE question_id=qid;
   END IF;
   FOR p IN SELECT value FROM jsonb_array_elements(coalesce(v->'parts','[]'::jsonb)) LOOP
    pid=(p->>'question_id')::uuid;
    IF EXISTS(SELECT 1 FROM public.questions WHERE id=pid) THEN RAISE EXCEPTION 'Split question already exists %',pid; END IF;
    IF p->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'choices') c WHERE c->>'key'=p->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid split key %',pid; END IF;
    IF p->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(p->'correct')='array' THEN p->'correct'->0 ELSE p->'correct' END,p->'correct') THEN RAISE EXCEPTION 'Invalid split numeric key %',pid; END IF;
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(pid,s.track_id,coalesce(p->>'topic',v->>'topic'),'medium',p->>'type',p->>'stem',p->'choices',coalesce(p->'assets','{}'::jsonb)||jsonb_build_object(
      'source','reviewed-bank-20260928','source_review_id',s.id,'source_code',s.source_code||':'||(p->>'label'),'source_document',s.source_document,'source_page',s.source_page,
      'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check','verification_note',p->>'note'));
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(pid,p->'correct',p->>'explanation');
   END LOOP;
  END IF;
  UPDATE public.est_source_review SET review_status=v->>'status',question_id=coalesce(qid,question_id),
   worked_answer=coalesce(v->'correct',worked_answer),duplicate_of=coalesce(v->>'duplicate_of',duplicate_of),
   review_note='Rechecked 2026-09-28. '||coalesce(v->>'note','')||CASE WHEN v ? 'explanation' THEN E'\nWorked solution: '||(v->>'explanation') ELSE '' END,
   updated_at=now() WHERE id=s.id;
  IF v ? 'parts' THEN UPDATE public.est_source_review SET review_note=review_note||E'\nAdditional separately published questions: '||(SELECT string_agg((partrow.value->>'label')||': '||(partrow.value->>'question_id')||'. '||(partrow.value->>'explanation'),E'\n') FROM jsonb_array_elements(v->'parts') partrow(value)) WHERE id=s.id; END IF;
 END LOOP;
END;
$review$;
SELECT count(*) applied_source_decisions FROM public.audit_log WHERE action='source_review_20260928';
